window.docContents[122].resolve({"/3___-General-results-of-representation-theory/3___9___-Problems/#chapter-03___section-3-9":{"contents":"\n\n\n\n\n\n\n\n\n\n\n\n","context":"Introduction to Representation Theory\u00093. General results of representation theory","header":"3.9. Problems","id":"/3___-General-results-of-representation-theory/3___9___-Problems/#chapter-03___section-3-9"},"/5___-Representations-of-finite-groups___-Further-results/5___12___-Representations-of-___S_n___/Specht-modules-for-partitions-_LPAR_n_RPAR____-_LPAR_1___n_RPAR____-and-small-n/#Chapter5___Example5___12___3":{"contents":"Example 5.12.3. For the partition \\lambda = (n), P_\\lambda = S_n, Q_\\lambda = \\{1\\}, so c_\\lambda is the symmetrizer, and hence V_\\lambda is the trivial representation.\nFor the partition \\lambda = (1, \\ldots, 1), Q_\\lambda = S_n, P_\\lambda = \\{1\\}, so c_\\lambda is the antisymmetrizer, and hence V_\\lambda is the sign representation.\n\nn = 3. For \\lambda = (2, 1), V_\\lambda = \\mathbb{C}^2.\n\nn = 4. For \\lambda = (2, 2), V_\\lambda = \\mathbb{C}^2; for \\lambda = (3, 1), V_\\lambda = \\mathbb{C}^3_-; for \\lambda = (2, 1, 1), V_\\lambda = \\mathbb{C}^3_+.\n\n\n\n","context":"Introduction to Representation Theory\u00095. Representations of finite groups: Further results\u00095.12. Representations of $S_n$\u0009Specht modules for partitions (n), (1^n), and small n","header":"Specht modules for partitions (n), (1^n), and small n","id":"/5___-Representations-of-finite-groups___-Further-results/5___12___-Representations-of-___S_n___/Specht-modules-for-partitions-_LPAR_n_RPAR____-_LPAR_1___n_RPAR____-and-small-n/#Chapter5___Example5___12___3"},"/5___-Representations-of-finite-groups___-Further-results/5___15___-The-Frobenius-character-formula/Footnote-on-lexicographic-ordering-of-sigma_LPAR_rho_RPAR_/#Chapter5___Discussion_footnote_5___15":{"contents":"---\n\n{}^2Another way to see this is to note that \\sigma(\\rho) \\leq \\rho lexicographically with equality if and only if \\sigma = 1, and subtracting both sides from the constant vector \\lambda + \\rho shows that \\lambda + \\rho - \\sigma(\\rho) \\geq \\lambda with equality if and only if \\sigma = 1.\n\n\n\n","context":"Introduction to Representation Theory\u00095. Representations of finite groups: Further results\u00095.15. The Frobenius character formula\u0009Footnote on lexicographic ordering of sigma(rho)","header":"Footnote on lexicographic ordering of sigma(rho)","id":"/5___-Representations-of-finite-groups___-Further-results/5___15___-The-Frobenius-character-formula/Footnote-on-lexicographic-ordering-of-sigma_LPAR_rho_RPAR_/#Chapter5___Discussion_footnote_5___15"},"/5___-Representations-of-finite-groups___-Further-results/5___2___-Algebraic-numbers-and-algebraic-integers/Algebraic-conjugates-of-sums-are-sums-of-algebraic-conjugates/#Chapter5___Lemma5___2___6___formalization":{"contents":"\n\n","context":"Introduction to Representation Theory\u00095. Representations of finite groups: Further results\u00095.2. Algebraic numbers and algebraic integers\u0009Algebraic conjugates of sums are sums of algebraic conjugates\u0009Algebraic conjugates of sums are sums of algebraic conjugates","header":"Formalization","id":"/5___-Representations-of-finite-groups___-Further-results/5___2___-Algebraic-numbers-and-algebraic-integers/Algebraic-conjugates-of-sums-are-sums-of-algebraic-conjugates/#Chapter5___Lemma5___2___6___formalization"},"/6___-Quiver-representations/6___1___-Problems/Problem-6___1___1___-Field-embeddings/#Chapter6___Problem6___1___1":{"contents":"Problem 6.1.1. Field embeddings. Recall that k(y_1, \\ldots, y_m) denotes the field of rational functions of y_1, \\ldots, y_m over a field k. Let f : k[x_1, \\ldots, x_n] \\to k(y_1, \\ldots, y_m) be an injective k-algebra homomorphism. Show that m \\geq n. (Look at the growth of dimensions of the spaces W_N of polynomials of degree N in x_i and their images under f as N \\to \\infty.) Deduce that if f : k(x_1, \\ldots, x_n) \\to k(y_1, \\ldots, y_m) is a k-linear field embedding, then m \\geq n.\n\n\n\n","context":"Introduction to Representation Theory\u00096. Quiver representations\u00096.1. Problems\u0009Problem 6.1.1: Field embeddings","header":"Problem 6.1.1: Field embeddings","id":"/6___-Quiver-representations/6___1___-Problems/Problem-6___1___1___-Field-embeddings/#Chapter6___Problem6___1___1"},"/6___-Quiver-representations/6___6___-Reflection-functors/Proposition-6___6___8___-Dimension-vector-under-reflection-is-s_i_LPAR_d_LPAR_V_RPAR__RPAR_/#Chapter6___Proposition6___6___8":{"contents":"Proposition 6.6.8. Let Q be a quiver and let V be a representation of Q.\n\n(1) Let i \\in Q be a sink and let V be surjective at i. Then\n\n\nd(F_i^+ V) = s_i(d(V)).\n\n\n(2) Let i \\in Q be a source and let V be injective at i. Then\n\n\nd(F_i^- V) = s_i(d(V)).\n\n\nProof. We only prove the first statement; the second one follows similarly. Let i \\in Q be a sink and let\n\n\n\\varphi : \\bigoplus_{j \\to i} V_j \\to V_i\n\n\nbe surjective. Let K = \\ker \\varphi. Then\n\n\n\\dim K = \\sum_{j \\to i} \\dim V_j - \\dim V_i.\n\n\nTherefore we get\n\n\n\\left( d(F_i^+ V) - d(V) \\right)_i = \\sum_{j \\to i} \\dim V_j - 2 \\dim V_i = -B(d(V), \\alpha_i)\n\n\nand\n\n\n\\left( d(F_i^+ V) - d(V) \\right)_j = 0, \\quad j \\neq i.\n\nThis implies\n\n\nd(F_i^+ V) - d(V) = -B(d(V), \\alpha_i) \\alpha_i\n\n\n\n\\iff d(F_i^+ V) = d(V) - B(d(V), \\alpha_i) \\alpha_i = s_i(d(V)).\n\n\n\\square\n\n\n\n","context":"Introduction to Representation Theory\u00096. Quiver representations\u00096.6. Reflection functors\u0009Proposition 6.6.8: Dimension vector under reflection is s_i(d(V))","header":"Proposition 6.6.8: Dimension vector under reflection is s_i(d(V))","id":"/6___-Quiver-representations/6___6___-Reflection-functors/Proposition-6___6___8___-Dimension-vector-under-reflection-is-s_i_LPAR_d_LPAR_V_RPAR__RPAR_/#Chapter6___Proposition6___6___8"}});